"""Publish notices with the firmware; run after preparing pinned dependencies."""
from pathlib import Path
import hashlib, json, re

ROOT = Path(__file__).resolve().parents[1]
SDK = ROOT/'.tools/dirtyjtag-build/sdk'
DEST = ROOT/'public/firmware/dirtyjtag'
DEST.mkdir(parents=True, exist_ok=True)
sections = ['Yosis BL616 DirtyJTAG firmware\nSources and modifications: hardware/dirtyjtag/README.md\n'
            'Sipeed signed loader: unchanged binary supplied by the pinned DirtyJTAG repository.\n'
            'USB descriptor changes are generated by scripts/build-dirtyjtag.py.\n']
for label, file in [('DirtyJTAG upstream (MIT)', ROOT/'hardware/dirtyjtag/upstream/LICENSE'),
                    ('Bouffalo SDK (Apache-2.0)', SDK/'LICENSE')]:
    sections.append(label+'\n\n'+file.read_text(encoding='utf-8'))
notices = {}
for file in SDK.rglob('*'):
    if file.suffix not in {'.c', '.h'}: continue
    text = file.read_text(encoding='utf-8', errors='replace')
    for block in re.findall(r'/\*.*?\*/', text[:12000], flags=re.S):
        if ('Copyright' in block or 'COPYRIGHT' in block) and any(word in block for word in ['SPDX', 'Redistribution', 'Permission', 'redistribution']):
            notices.setdefault(block, []).append(file.relative_to(SDK).as_posix())
            break
for block, files in sorted(notices.items(), key=lambda item: item[1][0]):
    sections.append('SDK source notices: '+', '.join(files)+'\n\n'+block)
(DEST/'THIRD-PARTY-NOTICES.txt').write_text('\n\n---\n\n'.join(sections), encoding='utf-8')

source = 'tools/bflb_tools/bouffalo_flash_cube/chips/bl616/efuse_bootheader/flash_para.bin'
params = SDK/source
if params.exists():
    data = params.read_bytes()
    if len(data) != 84 or hashlib.sha256(data).hexdigest() != '002c41f38bb652bdaf89136183aaef70ae11abbf85f554a59d7242748f32e1e0':
        raise ValueError('Pinned BL616 flash parameters changed')
    manifest = {'version': 1, 'sdk': '6ebf1d053287e0417bb37e2322dfda9665febf86', 'source': source,
                'gitBlob': 'a49010c26d21ed9e336bbe569fff74f0b2e45c26',
                'parameters': {'c86016': {'hex': data.hex(), 'sha256': hashlib.sha256(data).hexdigest()}}}
    (ROOT/'src/lib/bl616-flash-parameters.json').write_text(json.dumps(manifest, indent=2)+'\n')
print('Published firmware license notices:', len(notices))
